"""Fusion 360 script: chip chip1_rinse_dissociation_quench_wash_encapsulation (44.5 x 72.5 mm), generated by autochip/cad.py from chips/chip1_rinse_dissociation_quench_wash_encapsulation.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 2 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [44.5, 72.5]
PARTS = [["culture_1", "culture_chamber_param"], ["quench_join", "merge"], ["quench_mix", "mixer"], ["cell_wash", "spiral_separator"], ["core_join", "merge"], ["core_mix", "mixer"], ["droplets_1", "cross_junction"]]
CHANNELS = [["ch_inlet_1_culture_1", 0.5, [[2.5, 63.15], [4.7, 63.15]]], ["ch_culture_1_quench_join", 0.5, [[24.7, 63.15], [26.4, 63.15]]], ["ch_quench_join_quench_mix", 0.5, [[29.4, 63.15], [31.1, 63.15]]], ["ch_quench_mix_cell_wash", 0.5, [[39.6, 63.15], [40.4, 63.15], [40.4, 41.25], [39.8, 41.25]]], ["ch_cell_wash_core_join", 0.5, [[21.4, 41.25], [19.7, 41.25]]], ["ch_core_join_core_mix", 0.5, [[16.7, 41.25], [15.0, 41.25]]], ["ch_core_mix_droplets_1", 0.5, [[6.5, 41.25], [4.1, 41.25], [4.1, 14.35], [4.7, 14.35]]], ["ch_droplets_1_outlet_1", 0.5, [[24.7, 14.35], [42.0, 14.35]]], ["ch_reagent_line_in_culture_1", 0.5, [[14.7, 70.0], [14.7, 68.15]]], ["ch_culture_1_culture_1_waste_out", 0.5, [[14.7, 58.15], [14.7, 56.3]]], ["ch_quench_medium_in_quench_join", 0.5, [[27.9, 70.0], [27.9, 64.65]]], ["ch_wash_buffer_in_cell_wash", 0.5, [[30.6, 52.3], [30.6, 50.45]]], ["ch_cell_wash_cell_wash_waste_out", 0.5, [[30.6, 32.05], [30.6, 30.2]]], ["ch_core_solution_in_core_join", 0.5, [[18.2, 52.3], [18.2, 42.75]]], ["ch_shell_polymer_in_droplets_1", 0.5, [[14.7, 26.2], [14.7, 24.35]]], ["ch_fluorinated_oil_in_droplets_1", 0.5, [[14.7, 2.5], [14.7, 4.35]]]]
OUTLINES = [["ch_inlet_1_culture_1", [[2.5, 63.4], [4.7, 63.4], [4.7, 62.9], [2.5, 62.9]]], ["ch_culture_1_quench_join", [[24.7, 63.4], [26.4, 63.4], [26.4, 62.9], [24.7, 62.9]]], ["ch_quench_join_quench_mix", [[29.4, 63.4], [31.1, 63.4], [31.1, 62.9], [29.4, 62.9]]], ["ch_quench_mix_cell_wash", [[39.6, 63.4], [40.65, 63.4], [40.65, 41.0], [39.8, 41.0], [39.8, 41.5], [40.15, 41.5], [40.15, 62.9], [39.6, 62.9]]], ["ch_cell_wash_core_join", [[21.4, 41.0], [19.7, 41.0], [19.7, 41.5], [21.4, 41.5]]], ["ch_core_join_core_mix", [[16.7, 41.0], [15.0, 41.0], [15.0, 41.5], [16.7, 41.5]]], ["ch_core_mix_droplets_1", [[6.5, 41.0], [4.35, 41.0], [4.35, 14.6], [4.7, 14.6], [4.7, 14.1], [3.85, 14.1], [3.85, 41.5], [6.5, 41.5]]], ["ch_droplets_1_outlet_1", [[24.7, 14.6], [42.0, 14.6], [42.0, 14.1], [24.7, 14.1]]], ["ch_reagent_line_in_culture_1", [[14.95, 70.0], [14.95, 68.15], [14.45, 68.15], [14.45, 70.0]]], ["ch_culture_1_culture_1_waste_out", [[14.95, 58.15], [14.95, 56.3], [14.45, 56.3], [14.45, 58.15]]], ["ch_quench_medium_in_quench_join", [[28.15, 70.0], [28.15, 64.65], [27.65, 64.65], [27.65, 70.0]]], ["ch_wash_buffer_in_cell_wash", [[30.85, 52.3], [30.85, 50.45], [30.35, 50.45], [30.35, 52.3]]], ["ch_cell_wash_cell_wash_waste_out", [[30.85, 32.05], [30.85, 30.2], [30.35, 30.2], [30.35, 32.05]]], ["ch_core_solution_in_core_join", [[18.45, 52.3], [18.45, 42.75], [17.95, 42.75], [17.95, 52.3]]], ["ch_shell_polymer_in_droplets_1", [[14.95, 26.2], [14.95, 24.35], [14.45, 24.35], [14.45, 26.2]]], ["ch_fluorinated_oil_in_droplets_1", [[14.45, 2.5], [14.45, 4.35], [14.95, 4.35], [14.95, 2.5]]]]
PORTS = [["inlet_1", 2.5, 63.15, 1.0], ["outlet_1", 42.0, 14.35, 1.0], ["reagent_line_in", 14.7, 70.0, 1.0], ["culture_1_waste_out", 14.7, 56.3, 1.0], ["quench_medium_in", 27.9, 70.0, 1.0], ["wash_buffer_in", 30.6, 52.3, 1.0], ["cell_wash_waste_out", 30.6, 30.2, 1.0], ["core_solution_in", 18.2, 52.3, 1.0], ["shell_polymer_in", 14.7, 26.2, 1.0], ["fluorinated_oil_in", 14.7, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip1_rinse_dissociation_quench_wash_encapsulation outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip1_rinse_dissociation_quench_wash_encapsulation channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
